SELECT     concat(cast(cast(tjzq as int) % 100 as varchar), '月') as month,     round(sum(loan_qmdkye) / nullif(sum(deposit_qmzgzhye), 0) * 100, 2 ) as cdb FROM (     SELECT         substring(tjzq, 5,2) as tjzq,         sum(qmdkye) as loan_qmdkye,         0 as deposit_qmzgzhye     FROM dws_bus_ln_ned     WHERE left(tjzq, 4) = #{ssnd}     group by substring(tjzq, 5,2)     UNION ALL     SELECT         substring(tjzq, 5,2) as tjzq,         0 as loan_qmdkye,         sum(qmzgzhye) as deposit_qmzgzhye     FROM dws_csr_per_ned     WHERE left(tjzq, 4) = #{ssnd}     group by substring(tjzq, 5, 2) ) t GROUP BY cast(cast(tjzq as int) % 100 as varchar) ORDER BY cast(cast(tjzq as int) % 100 as varchar) 
